import {
  Timestamps2
} from "./repository-cache-qfa1cgps.js";
import {
  ProjectTable2
} from "./repository-cache-rj3eygr5.js";

// src/permission/sql.ts
import { sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
var PermissionTable2 = sqliteTable("permission", {
  id: text().$type().primaryKey(),
  project_id: text().$type().notNull().references(() => ProjectTable2.id, { onDelete: "cascade" }),
  action: text().notNull(),
  resource: text().notNull(),
  ...Timestamps2
}, (table) => [uniqueIndex("permission_project_action_resource_idx").on(table.project_id, table.action, table.resource)]);

export { PermissionTable2 };
